#!/bin/bash
# This script runs when the server-db docker image is built (copied into
# /docker-entrypoint-initdb.d/ by server/database/Dockerfile). It imports the
# base database structure and creates the database for the tests. The _init.sql
# it consumes is generated by e2e_images.sh (buildSQL).

DATABASE_NAME="juralio"
DATABASE_USER="juralio"
DB_DUMP_LOCATION="/tmp/psql_data/init.sql"

echo "*** CREATING DATABASE ***"
set -e

psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" <<-EOSQL
  CREATE USER "$DATABASE_USER" WITH LOGIN INHERIT CREATEDB CREATEROLE NOREPLICATION PASSWORD 'juralio';
  CREATE DATABASE "$DATABASE_NAME" OWNER "$DATABASE_USER";
EOSQL

# import sql_dump
psql "$DATABASE_NAME" < "$DB_DUMP_LOCATION";
echo "*** DATABASE CREATED! ***"